export const CATEGORY_BY_ID = Object.fromEntries(CATEGORIES.map(c => [c.id, c]))
export const CATEGORY_BY_SLUG = Object.fromEntries(CATEGORIES.map(c => [c.slug, c]))
export const CATEGORY_PATH_SET = new Set(CATEGORIES.map(c => c.path))

export function categoryPathById(id) {
  const c = CATEGORY_BY_ID[id]
  return c ? c.path : null
}

export function categoryPathBySlug(slug) {
  const c = CATEGORY_BY_SLUG[slug]
  return c ? c.path : null
}

export function categoryUrlBySlug(slug) {
  const p = categoryPathBySlug(slug)
  return p ? `/${p}/` : null
}
